// Normalise the employee code: trim, uppercase, strip internal spaces.
const input = $input.first().json;
const raw = (input.employee_code || '').toString();
const normalised = raw.trim().toUpperCase().replace(/\s+/g, '');
return [{ json: { employee_code: normalised, session_id: input.session_id || '' } }];

// Resolve found/not-found/inactive/locked and build public employee object.
const rows = $input.all();
const row = rows.length && rows[0].json && rows[0].json['Employee Code'] ? rows[0].json : null;
const code = $('Normalise Code').first().json.employee_code;
const callerInput = $('When Executed by Another Workflow').first().json;
const defaults = callerInput.settings_defaults || {};
const catalog = callerInput.catalog || [];
const defaultTimezone = defaults.DEFAULT_TIMEZONE || 'Asia/Kolkata';

if (!row) {
  return [{ json: { ok: false, code: 'UNKNOWN_EMPLOYEE_CODE', employee_code: code } }];
}

if ((row.Status || '').toString().trim().toUpperCase() !== 'ACTIVE') {
  return [{ json: { ok: false, code: 'EMPLOYEE_INACTIVE', employee_code: code } }];
}

// Check Locked Until timestamp
const lockedUntilStr = (row['Locked Until'] || '').toString().trim();
if (lockedUntilStr) {
  const lockedUntil = new Date(lockedUntilStr);
  if (!isNaN(lockedUntil.getTime()) && lockedUntil > new Date()) {
    return [{ json: { ok: false, code: 'EMPLOYEE_LOCKED', until: lockedUntilStr, employee_code: code } }];
  }
}

const projectsRaw = (row.Projects || '').toString().trim();
const assignedProjectNames = projectsRaw ? projectsRaw.split(',').map(p => p.trim()).filter(Boolean) : [];

// Build assignment: intersect employee projects with catalog
let allowedProjects = [];
if (assignedProjectNames.length > 0) {
  allowedProjects = catalog.filter(c => assignedProjectNames.includes(c.project));
} else {
  allowedProjects = catalog;
}

if (allowedProjects.length === 0) {
  return [{ json: { ok: true, unassigned: true, employee_code: code } }];
}

const timezone = (row.Timezone || '').toString().trim() || defaultTimezone;
const maxHoursCell = (row['Max Hours Per Day'] || '').toString().trim();
const maxHoursPerDay = maxHoursCell !== '' && !isNaN(Number(maxHoursCell)) ? Number(maxHoursCell) : null;

return [{
  json: {
    ok: true,
    employee: {
      code: (row['Employee Code'] || code).toString().trim().toUpperCase(),
      name: (row.Name || '').toString().trim(),
      timezone,
      projects: assignedProjectNames,
      max_hours_per_day: maxHoursPerDay
    },
    assignment: {
      projects: allowedProjects
    }
  }
}];
